import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:hive_flutter/hive_flutter.dart'  import 'core/app_router.dart'  import 'api/api_client.dart'    void main() async {    WidgetsFlutterBinding.ensureInitialized()    await Hive.initFlutter()    ApiClient().init()    runApp(const ProviderScope(child: MyApp()))  }    class MyApp extends StatelessWidget {    const MyApp({super.key})      @override    Widget build(BuildContext context) {      return MaterialApp.router(        title: 'Мир Самозанятых',        debugShowCheckedModeBanner: false,        theme: ThemeData(          colorScheme: ColorScheme.fromSeed(            seedColor: const Color(0xFF2563EB),            brightness: Brightness.light,          ),          useMaterial3: true,          fontFamily: 'Roboto',          appBarTheme: const AppBarTheme(            centerTitle: true,            elevation: 0,            backgroundColor: Color(0xFF2563EB),            foregroundColor: Colors.white,          ),          cardTheme: CardTheme(            elevation: 2,            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),          ),          bottomNavigationBarTheme: const BottomNavigationBarThemeData(            selectedItemColor: Color(0xFF2563EB),            unselectedItemColor: Color(0xFF94A3B8),            type: BottomNavigationBarType.fixed,          ),        ),        darkTheme: ThemeData(          colorScheme: ColorScheme.fromSeed(            seedColor: const Color(0xFF2563EB),            brightness: Brightness.dark,          ),          useMaterial3: true,        ),        routerConfig: appRouter,      )    }  }